13	/// `PhotoEntryCubit`'s own sealed state hierarchy — separate from
14	/// `TextEntryState`/`AudioCaptureState` (Boundaries: "own sealed
15	/// `PhotoCaptureState`"). No common base-class field, same rationale as
16	/// `AudioCaptureState`: [PhotoIdle] has nothing in common with
17	/// [PhotoRecognized], for instance.
18	sealed class PhotoCaptureState {
19	  const PhotoCaptureState();
20	}
21	
22	/// The state immediately after the modal opens on the Foto tab, after
23	/// leaving mid-pick/mid-OCR (Never: this story's trivial cross-tab
24	/// case), and the state a fresh `PhotoEntryCubit` always starts in.
25	/// `InsertionModal`'s own `_FotoTab` renders the Câmera/Galeria capture
26	/// buttons for this state.
27	class PhotoIdle extends PhotoCaptureState {
28	  const PhotoIdle();
29	}
30	
31	/// A photo was picked, `MediaRepository.recognizeText()` in flight —
32	/// `_FotoTab` shows a thumbnail + "Reconhecendo texto..." for the whole
33	/// duration of this state (Acceptance Criteria). No separate "recording"-
34	/// style intermediate phase (Design Notes): picking is one blocking OS
35	/// call, so [PhotoIdle] goes straight here once the picker returns a file.
36	class PhotoProcessing extends PhotoCaptureState {
37	  const PhotoProcessing({required this.path, required this.mimeType});
38	
39	  final String path;
40	  final String mimeType;
41	}
42	
43	/// OCR succeeded with usable text — [text] is editable before Salvar
44	/// (Acceptance Criteria), mirrored by [PhotoEntryCubit.updateText].
45	/// [saving] folds `TextEntrySaving`'s role into this same state, same
46	/// convention as `AudioTranscribed.saving`.
47	class PhotoRecognized extends PhotoCaptureState {
48	  const PhotoRecognized({
49	    required this.path,
50	    required this.mimeType,
51	    required this.text,
52	    required this.saving,
53	  });
54	
55	  final String path;
56	  final String mimeType;
57	  final String text;
58	  final bool saving;
59	
60	  PhotoRecognized copyWith({String? text, bool? saving}) => PhotoRecognized(
61	    path: path,
62	    mimeType: mimeType,
63	    text: text ?? this.text,
64	    saving: saving ?? this.saving,
65	  );
66	}
67	
68	/// A save attempt succeeded — `InsertionModal`'s listener reacts to this
69	/// exactly like `TextEntrySaved`/`AudioSaved` (announce, then pop).
70	/// Terminal, same rationale as those two states' own docs.
71	class PhotoSaved extends PhotoCaptureState {
72	  const PhotoSaved();
73	}
74	
75	/// The 3-way discriminator driving `_FotoTab`'s three distinct error
76	/// branches (Design Notes: "a discriminator is clearer than overloading
77	/// nullability tricks" — unlike `AudioError`'s binary `canRetry`, Photo
78	/// has two distinct non-retryable backend codes needing different UI).
79	enum PhotoErrorKind {
80	  /// `Failure.ocrNoText` — "Tentar novamente" (re-OCRs the same image)
81	  /// and "Salvar só a foto" (saves a fixed placeholder) are both offered.
82	  ocrNoText,
83	
84	  /// `Failure.payloadTooLarge` — no retry, no save-without-text; the only
85	  /// way forward is picking a different photo.
86	  payloadTooLarge,
87	
88	  /// Any other `Failure` — a generic OCR-call failure ([text] `null`,
89	  /// "Tentar novamente" re-OCRs) or a save failure ([text] non-null,
90	  /// re-running the failed call means tapping Salvar again, same shape
91	  /// as `AudioError`).
92	  generic,
93	}
94	
95	/// The last attempt failed — covers every failure row of the I/O matrix:
96	/// `OCR_NO_TEXT`, `PAYLOAD_TOO_LARGE`, a generic OCR-call failure, or a
97	/// save failure (non-null [text]).
98	class PhotoError extends PhotoCaptureState {
99	  const PhotoError({
100	    required this.path,
101	    required this.mimeType,
102	    required this.message,
103	    required this.kind,
104	    this.text,
105	  });
106	
107	  final String path;
108	  final String mimeType;
109	  final String message;
110	  final PhotoErrorKind kind;
111	
112	  /// Non-null only for a save failure ([PhotoErrorKind.generic]) — lets
113	  /// `_FotoTab` keep rendering the editable text field under the inline
114	  /// error, same as `AudioError.text`/`TextEntryError`'s own rendering.
115	  final String? text;
116	}
117	
118	/// Drives the Foto tab's pick -> processingOcr -> recognized/error
119	/// pipeline (Intent). A fresh, `get_it`-factory-scoped instance per "+"
120	/// tap, same convention as `TextEntryCubit`/`AudioEntryCubit` —
121	/// [PhotoPicker]/[MediaRepository] themselves stay long-lived `get_it`
122	/// singletons (`capture_injection.dart`).
123	class PhotoEntryCubit extends Cubit<PhotoCaptureState> {
124	  PhotoEntryCubit(this._photoPicker, this._mediaRepository, this._tracker)
125	    : super(const PhotoIdle());
126	
127	  final PhotoPicker _photoPicker;
128	  final MediaRepository _mediaRepository;
129	
130	  /// spec-4-2 — the shared [PendingEntryWriteTracker], swapped in for a
131	  /// direct `EntriesRepository` dependency (identical `create()` contract,
132	  /// Code Map: "no call-site logic change").
133	  final PendingEntryWriteTracker _tracker;
134	
135	  static const _noTextPlaceholder =
136	      'Registro fotográfico (sem texto reconhecido)';
137	
138	  /// Bumped by [cancel] (and by every pick/retry attempt) so an in-flight
139	  /// picker/OCR continuation can tell "the user already left the Foto tab"
140	  /// apart from "nothing has changed since I started" — same role
141	  /// `AudioEntryCubit._generation` plays for the picker call and the OCR
142	  /// network call here (Boundaries).
143	  int _generation = 0;
144	
145	  /// Guards against a second overlapping picker call (e.g. a fast
146	  /// double-tap on Câmera before the UI rebuilds past [PhotoIdle]).
147	  bool _picking = false;
148	
149	  Future<void> pickFromCamera() => _pick(_photoPicker.pickFromCamera);
150	
151	  Future<void> pickFromGallery() => _pick(_photoPicker.pickFromGallery);
152	
153	  Future<void> _pick(Future<PickedPhoto?> Function() pick) async {
154	    final current = state;
155	    final canPick =
156	        !_picking &&
157	        (current is PhotoIdle ||
158	            (current is PhotoError &&
159	                current.kind == PhotoErrorKind.payloadTooLarge));
160	    if (!canPick) {
161	      return;
162	    }
163	    // A fresh pick replacing a previous `payloadTooLarge` error's own
164	    // (never-OCR'd, now-abandoned) file — Review finding: without this,
165	    // that file leaked on disk forever once this new pick's own file
166	    // takes over `state`. Deleted unconditionally right away (Review
167	    // finding): this old file is abandoned the moment a new pick starts,
168	    // regardless of whether that new pick succeeds, is canceled, or
169	    // throws — the earlier code only deleted it on success, leaking it
170	    // on every other exit path.
171	    final previousPath = current is PhotoError ? current.path : null;
172	    if (previousPath != null) {
173	      unawaited(_deletePickedFile(previousPath));
174	    }
175	    _picking = true;
176	    final generation = ++_generation;
177	    PickedPhoto? photo;
178	    try {
179	      photo = await pick();
180	    } catch (_) {
181	      // A thrown PlatformException (native-side error) must never escape
182	      // uncaught — treated the same as a plain user cancel, since this
183	      // story offers no dedicated "picker failed" UI (not in the I/O
184	      // matrix).
185	      _picking = false;
186	      if (isClosed || generation != _generation) {
187	        return;
188	      }
189	      emit(const PhotoIdle());
190	      return;
191	    }
192	    _picking = false;
193	    if (isClosed || generation != _generation) {
194	      // Review finding: without this, a photo picked just as the user
195	      // left the tab (or closed the whole modal) was discarded with no
196	      // cleanup — its OS temp file leaked forever.
197	      if (photo != null) {
198	        unawaited(_deletePickedFile(photo.path));
199	      }
200	      return;
201	    }
202	    if (photo == null) {
203	      // I/O matrix: "User cancels picker" -> stays on PhotoIdle's capture
204	      // buttons. If the re-pick was attempted from a `payloadTooLarge`
205	      // error, drop that stale error too rather than leaving it on
206	      // screen with nothing that produced it anymore.
207	      if (current is PhotoError) {
208	        emit(const PhotoIdle());
209	      }
210	      return;
211	    }
212	    emit(PhotoProcessing(path: photo.path, mimeType: photo.mimeType));
213	    await _recognize(photo.path, photo.mimeType, generation);
214	  }
215	
216	  Future<void> _recognize(String path, String mimeType, int generation) async {
217	    Uint8List bytes;
218	    try {
219	      bytes = await File(path).readAsBytes();
220	    } catch (_) {
221	      if (isClosed || generation != _generation) {
222	        return;
223	      }
224	      emit(
225	        PhotoError(
226	          path: path,
227	          mimeType: mimeType,
228	          message: 'Não foi possível ler a foto selecionada.',
229	          kind: PhotoErrorKind.generic,
230	        ),
231	      );
232	      return;
233	    }
234	    final result = await _mediaRepository.recognizeText(
235	      imageBytes: bytes,
236	      mimeType: mimeType,
237	    );
238	    // Guards a tab switch away mid-OCR (`cancel()`, below) that already
239	    // reset the state by the time this resolves — without this, a stale
240	    // OCR result would still land and resurrect a flow the user left.
241	    if (isClosed || generation != _generation) {
242	      return;
243	    }
244	    result.match(
245	      (failure) => emit(
246	        PhotoError(
247	          path: path,
248	          mimeType: mimeType,
249	          message: failure.message,
250	          kind: switch (failure) {
251	            OcrNoText() => PhotoErrorKind.ocrNoText,
252	            PayloadTooLarge() => PhotoErrorKind.payloadTooLarge,
253	            _ => PhotoErrorKind.generic,
254	          },
255	        ),
256	      ),
257	      (ocr) => emit(
258	        PhotoRecognized(
259	          path: path,
260	          mimeType: mimeType,
261	          text: ocr.text,
262	          saving: false,
263	        ),
264	      ),
265	    );
266	  }
267	
268	  /// "Tentar novamente" — re-OCRs the same image for an [OcrNoText]
269	  /// error or a generic OCR-call failure ([PhotoError.text] `null`). A
270	  /// no-op for [PhotoErrorKind.payloadTooLarge] (I/O matrix: no retry
271	  /// offered) and for a generic *save* failure (non-null [PhotoError.
272	  /// text]) — that case's own retry is tapping Salvar again, handled by
273	  /// [save] directly, mirroring `AudioEntryCubit.retry()`.
274	  Future<void> retry() async {
275	    final current = state;
276	    if (current is! PhotoError ||
277	        current.text != null ||
278	        current.kind == PhotoErrorKind.payloadTooLarge) {
279	      return;
280	    }
281	    final generation = ++_generation;
282	    emit(PhotoProcessing(path: current.path, mimeType: current.mimeType));
283	    await _recognize(current.path, current.mimeType, generation);
284	  }
285	
286	  /// "Salvar só a foto" — only valid from an [OcrNoText] error; saves the
287	  /// fixed, non-empty placeholder content (the contract's
288	  /// `content.minLength: 1` forbids an empty save).
289	  Future<void> saveWithoutText() async {
290	    final current = state;
291	    if (current is! PhotoError || current.kind != PhotoErrorKind.ocrNoText) {
292	      return;
293	    }
294	    await _save(
295	      path: current.path,
296	      mimeType: current.mimeType,
297	      text: _noTextPlaceholder,
298	    );
299	  }
300	
301	  /// Mirrors the Texto/Áudio fields' own `updateText` — keeps the
302	  /// recognized text editable before Salvar, and keeps a save-failure
303	  /// retry's text editable too (same as `AudioEntryCubit.updateText`'s
304	  /// own `AudioError` branch).
305	  void updateText(String text) {
306	    final current = state;
307	    if (current is PhotoRecognized && !current.saving) {
308	      emit(current.copyWith(text: text));
309	    } else if (current is PhotoError &&
310	        current.kind == PhotoErrorKind.generic &&
311	        current.text != null) {
312	      emit(
313	        PhotoError(
314	          path: current.path,
315	          mimeType: current.mimeType,
316	          message: current.message,
317	          kind: current.kind,
318	          text: text,
319	        ),
320	      );
321	    }
322	  }
323	
324	  /// I/O matrix's "Happy path"/"Save fails" rows: fires `POST /entries`
325	  /// with `source: photo` for the current (possibly edited) recognized
326	  /// text. Also callable from a save-failure [PhotoError] (non-null
327	  /// [PhotoError.text]), mirroring `AudioEntryCubit.save()`'s own
328	  /// re-save-on-retry behavior.
329	  Future<void> save() async {
330	    final current = state;
331	    final String path;
332	    final String mimeType;
333	    final String text;
334	    if (current is PhotoRecognized && !current.saving) {
335	      path = current.path;
336	      mimeType = current.mimeType;
337	      text = current.text.trim();
338	    } else if (current is PhotoError &&
339	        current.kind == PhotoErrorKind.generic &&
340	        current.text != null) {
341	      path = current.path;
342	      mimeType = current.mimeType;
343	      text = current.text!.trim();
344	    } else {
345	      return;
346	    }
347	    if (text.isEmpty) {
348	      return;
349	    }
350	    await _save(path: path, mimeType: mimeType, text: text);
351	  }
352	
353	  Future<void> _save({
354	    required String path,
355	    required String mimeType,
356	    required String text,
357	  }) async {
358	    emit(
359	      PhotoRecognized(path: path, mimeType: mimeType, text: text, saving: true),
360	    );
361	    final result = await _tracker.create(
362	      content: text,
363	      source: EntrySource.photo,
364	    );
365	    // Mirrors `AudioEntryCubit.save()`'s own `isClosed` guard — this
366	    // cubit's `close()` can race the awaited call above (e.g. the
367	    // modal's barrier is dismissed mid-save).
368	    if (isClosed) {
369	      return;
370	    }
371	    result.match(
372	      (failure) => emit(
373	        PhotoError(
374	          path: path,
375	          mimeType: mimeType,
376	          message: failure.message,
377	          kind: PhotoErrorKind.generic,
378	          text: text,
379	        ),
380	      ),
381	      (_) {
382	        // Review finding: the picked photo's temp file (written by
383	        // `image_picker` itself, not by this class, but still this
384	        // cubit's responsibility to clean up once it's done with it)
385	        // was never deleted after a successful save — fire-and-forget,
386	        // a deletion failure must never block the modal from closing.
387	        unawaited(_deletePickedFile(path));
388	        emit(const PhotoSaved());
389	      },
390	    );
391	  }
392	
393	  /// Called when the Foto tab loses focus mid-pick/mid-OCR
394	  /// (`InsertionModal`'s tab-switch listener) — I/O matrix's "Leave tab
395	  /// mid-pick/OCR" row: the in-flight picker/OCR call is discarded, no
396	  /// `create()` ever fires. A no-op for every other state when
397	  /// [discardPreserved] is `false` (the default) — in particular
398	  /// [PhotoRecognized]/[PhotoError], where the Never clause's trivial
399	  /// scope (resource safety only, not full Story 3.4 cancel-safety)
400	  /// means a tab switch must preserve the result rather than discard it
401	  /// — mirrors `AudioEntryCubit.cancel()`'s own `discardPreserved`
402	  /// convention exactly.
403	  ///
404	  /// [discardPreserved] — `InsertionModal.show()`'s `finally` also calls
405	  /// this (before `close()`) when the *whole modal* is dismissed (✕/
406	  /// swipe-down/barrier tap), not just the tab. In that case there's no
407	  /// "switch back to the tab later" to preserve for — the cubit is about
408	  /// to be closed — so a preserved [PhotoRecognized]/[PhotoError]'s
409	  /// picked-photo temp file would otherwise never be cleaned up and leak
410	  /// on disk forever (Review finding — the comment this replaced
411	  /// incorrectly claimed Foto "never creates a temp file of its own";
412	  /// `image_picker` does, every pick). Pass `true` only from that call
413	  /// site.
414	  Future<void> cancel({bool discardPreserved = false}) async {
415	    // Bumped unconditionally — including when the state below doesn't
416	    // match — so an in-flight `_pick`/`_recognize`/`retry` continuation
417	    // still sees the mismatch and aborts itself even while still awaiting
418	    // (Review-finding rationale mirrored from `AudioEntryCubit.cancel()`).
419	    _generation++;
420	    // Review finding: without this, leaving the Foto tab while the
421	    // native picker call itself (not yet `PhotoProcessing`) was still in
422	    // flight left `_picking` stuck `true` forever — the `_generation`
423	    // bump above already makes that stale continuation a no-op, so
424	    // resetting this eagerly is always safe.
425	    _picking = false;
426	    final current = state;
427	    if (current is PhotoProcessing) {
428	      unawaited(_deletePickedFile(current.path));
429	      emit(const PhotoIdle());
430	    } else if (discardPreserved) {
431	      final path = switch (current) {
432	        PhotoRecognized(path: final p) => p,
433	        PhotoError(path: final p) => p,
434	        _ => null,
435	      };
436	      if (path != null) {
437	        unawaited(_deletePickedFile(path));
438	      }
439	    }
440	  }
441	
442	  /// Best-effort cleanup for a picked-photo temp file this cubit is done
443	  /// with (saved successfully, abandoned for good by [cancel], or
444	  /// replaced by a fresh pick in [_pick]) — deletion failures are
445	  /// swallowed since nothing in the UI depends on this succeeding,
446	  /// mirroring `AudioEntryCubit._deleteRecordingFile()`.
447	  Future<void> _deletePickedFile(String path) async {
448	    try {
449	      await File(path).delete();
450	    } catch (_) {
451	      // Best-effort — a missing/already-deleted file, or a transient
452	      // disk error, is never worth surfacing to the user.
453	    }
454	  }
455	}
