10	/// Capture's one OCR call (`media-ocr`) — posts via the shared
11	/// `ApiClient`, mirroring `entries_remote_data_source.dart`'s pattern.
12	/// Base64-encodes the image bytes here, and only here (Boundaries) — no
13	/// other layer ever handles the raw bytes in that encoded form.
14	class MediaRemoteDataSource {
15	  MediaRemoteDataSource(this._apiClient);
16	
17	  final ApiClient _apiClient;
18	
19	  Future<Either<Failure, OcrResult>> recognizeText({
20	    required Uint8List imageBytes,
21	    required String mimeType,
22	  }) async {
23	    final result = await _apiClient.post(
24	      'media-ocr',
25	      data: {'image': base64Encode(imageBytes), 'mimeType': mimeType},
26	    );
27	    return result.flatMap((json) {
28	      try {
29	        final data = json['data'] as Map<String, dynamic>;
30	        return right(
31	          OcrResult(
32	            text: data['text'] as String,
33	            confidence: data['confidence'] as String,
34	          ),
35	        );
36	      } catch (error) {
37	        // A 200 response that doesn't match the expected shape is a
38	        // client-side parse failure, never a backend-sent code — maps to
39	        // the local-only `malformedResponse` (RNF09: no exception escapes
40	        // unmapped).
41	        return left(Failure.malformedResponse(message: error.toString()));
42	      }
43	    });
44	  }
45	}
