338	  void _onTextEntryStateChange(BuildContext context, TextEntryState state) {
339	    // Review finding: a tab switch (re-emitted as `TextEntryIdle`,
340	    // same as every keystroke) previously went unannounced —
341	    // detected here by comparing against the last tab seen, so a
342	    // plain keystroke (same `activeTab`) never re-triggers it.
343	    if (state.activeTab != _lastAnnouncedTab) {
344	      final previousTab = _lastAnnouncedTab;
345	      _lastAnnouncedTab = state.activeTab;
346	      _announce('Aba ${_tabLabels[state.activeTab]} selecionada');
347	      // Correction: entering Áudio used to call
348	      // `AudioEntryCubit.startRecording()` immediately — the raw
349	      // prototype's own `isAudioIdle` block shows a round microphone
350	      // button and "Toque para gravar" first; recording only starts once
351	      // the user taps it (`_AudioIdleView`'s own `onTap`). Leaving the
352	      // tab still stops/releases the recorder (I/O matrix: "Leave tab
353	      // mid-recording"), never the full Story 3.4 cancel choreography.
354	      if (previousTab == CaptureTab.audio) {
355	        unawaited(context.read<AudioEntryCubit>().cancel());
356	      }
357	      // spec-3-3's Code Map: leaving Foto mid-pick/mid-OCR discards the
358	      // in-flight picker/OCR call (I/O matrix: "Leave tab mid-pick/OCR")
359	      // — unlike Áudio, entering Foto never starts anything on its own
360	      // (picking only ever starts from an explicit Câmera/Galeria tap).
361	      if (previousTab == CaptureTab.foto) {
362	        unawaited(context.read<PhotoEntryCubit>().cancel());
363	      }
364	    }
365	    switch (state) {
366	      case TextEntrySaved():
367	        // I/O matrix: "success closes the modal". Review finding:
368	        // wait for the announcement to actually be sent before
369	        // popping — previously fired-and-forgot in the same tick,
370	        // risking the announcement being cut off by the dismiss
371	        // transition.
372	        unawaited(
373	          _announce('Registro salvo').then((_) {
374	            if (context.mounted) {
375	              _unfocusAndPop(context);
376	            }
377	          }),
378	        );
379	      case TextEntrySaving():
380	        _announce('Salvando registro');
381	      case TextEntryError():
382	        _announce(state.message);
383	      case TextEntryIdle():
384	        break;
385	    }
